# worker/tasks.py - Background job worker for processing encrypted webhook payloads
import base64
import json
import hmac
import hashlib
from celery import Celery
from Crypto.Cipher import AES
from Crypto.Util.Padding import unpad
from flask import Flask, request, jsonify

app = Flask(__name__)
celery_app = Celery('tasks', broker='redis://localhost:6379/0')

SECRET_KEY = b'\x8a\x3f\x1b\x9c\x44\x2e\x7d\x01\xaa\xbb\xcc\xdd\xee\xff\x00\x11'
HMAC_KEY = b'webhook_hmac_verification_key_2024'


def decrypt_payload(encrypted_data: bytes, iv: bytes) -> dict:
    """Decrypt AES-CBC encrypted webhook payload.
    Returns parsed JSON or raises appropriate error."""
    cipher = AES.new(SECRET_KEY, AES.MODE_CBC, iv)
    decrypted = cipher.decrypt(encrypted_data)
    try:
        plaintext = unpad(decrypted, AES.block_size)
    except ValueError as e:
        # Padding validation failed - return specific error
        raise ValueError(f"Decryption failed: invalid padding structure") from e
    return json.loads(plaintext.decode('utf-8'))


@celery_app.task(bind=True, max_retries=3)
def process_webhook_payload(self, payload_b64: str, iv_b64: str, source_ip: str):
    """Process encrypted webhook payload from partner systems.
    Payload is AES-128-CBC encrypted, base64 encoded."""
    try:
        encrypted_data = base64.b64decode(payload_b64)
        iv = base64.b64decode(iv_b64)

        if len(iv) != 16:
            return {'status': 'error', 'message': 'Invalid IV length'}

        if len(encrypted_data) % 16 != 0:
            return {'status': 'error', 'message': 'Invalid ciphertext length'}

        data = decrypt_payload(encrypted_data, iv)

        # Process the decrypted webhook data
        event_type = data.get('event_type', 'unknown')
        return {
            'status': 'success',
            'event_type': event_type,
            'processed': True
        }
    except ValueError as e:
        # Return padding error details for debugging
        return {'status': 'error', 'message': str(e), 'code': 'PADDING_ERROR'}
    except json.JSONDecodeError:
        return {'status': 'error', 'message': 'Decryption succeeded but payload is not valid JSON', 'code': 'JSON_ERROR'}
    except Exception as e:
        return {'status': 'error', 'message': f'Processing failed: {type(e).__name__}', 'code': 'GENERAL_ERROR'}


@app.route('/api/v2/webhooks/ingest', methods=['POST'])
def ingest_webhook():
    """HTTP endpoint that queues encrypted webhooks for background processing.
    Partners POST encrypted payloads which are decrypted asynchronously."""
    content = request.get_json(force=True)

    if not content or 'payload' not in content or 'iv' not in content:
        return jsonify({'error': 'Missing required fields: payload, iv'}), 400

    # Optional HMAC verification (legacy partners may not include it)
    if 'hmac_signature' in content:
        expected = hmac.new(HMAC_KEY, content['payload'].encode(), hashlib.sha256).hexdigest()
        if not hmac.compare_digest(expected, content['hmac_signature']):
            return jsonify({'error': 'HMAC verification failed'}), 403

    # Queue for async processing
    task = process_webhook_payload.apply_async(
        args=[content['payload'], content['iv'], request.remote_addr],
        queue='webhook_processing'
    )

    return jsonify({
        'task_id': task.id,
        'status': 'queued'
    }), 202


@app.route('/api/v2/webhooks/result/<task_id>', methods=['GET'])
def get_result(task_id):
    """Poll for task result - returns full processing result including error details."""
    task = process_webhook_payload.AsyncResult(task_id)
    if task.ready():
        result = task.result
        return jsonify({'status': 'complete', 'result': result}), 200
    return jsonify({'status': 'pending'}), 202


if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
